insert into public.posts(id,data) values ($i$2026-10-15-IG$i$,$j${"b": "المنشور 1: صورة واجهة المبنى بإضاءة نهار + الشعار. المنشور 2: لقطة قريبة ليد تفحص القفل الذكي. المنشور 3: خريطة مبسطة بالأحياء بألوان البراند.", "c": "المنشور 1 · من نحن\nهذي ذا كابيتال سويتس.\nنشغّل وحدات سكنية مفروشة بالشهر في الرياض، بنفس معايير الفندق: تنظيف، صيانة، دخول ذكي، وفريق يرد عليك.\nمن اليوم بنشارككم كيف نشتغل من الداخل: التجهيز، المعايير، والأرقام.\n\nالمنشور 2 · معاييرنا\nقبل ما نسلّم أي وحدة، تمر على قائمة فحص كاملة: [بنود قائمة الفحص].\nهذا معيارنا مع كل ساكن، مو مع الساكن الأول بس.\n\nالمنشور 3 · وين نشغّل\nنشغّل اليوم في [الأحياء المشغّلة حالياً].\nكل حي له طبيعته وسكانه، وبنعرّفكم عليهم حي حي.\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-10-15", "designLink": "", "f": "3 منشورات ثابتة 4:5 تُنشر معاً وتُثبّت أعلى الحساب", "im": ["img/Main.jpg", "img/W1-01b.jpg", "img/W1-01c.jpg"], "lastNote": "عايز اخلي التصاميم الاولى سواء 3 او 9 بشكل جريد على انستقرام", "lv": "A", "n": "تأكيد الأحياء المشغّلة حالياً، وبنود قائمة الفحص من التشغيل", "noteCount": 2, "p": "IG", "pubLink": "", "r": "", "s": "التعريف", "status": "design", "t": "إطلاق الحساب: صف التعريف (3 منشورات تُثبّت)", "updatedAt": "2026-10-07T14:19:46.164Z", "updatedBy": "u_qrJLJWChmzjL048TJIDtxw"}$j$::jsonb) on conflict (id) do update set data=excluded.data;
