insert into public.posts(id,data) values ($i$2026-10-18-IG$i$,$j${"b": "لقطات: الوصول للمبنى، رمز الدخول على شاشة الجوال، الباب يفتح، دخول الوحدة والإضاءة شغالة. نص على الشاشة لكل خطوة.", "c": "توصل، تفتح الباب من جوالك، وتلقى وحدتك جاهزة.\nبدون مفاتيح ولا انتظار استقبال.\nهذا الدخول الذكي في وحداتنا، خطوة بخطوة.\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-10-18", "designLink": "", "f": "ريلز 25 ثانية", "im": ["img/W1-02-1.jpg", "img/W1-02-2.jpg", "img/W1-02-3.jpg", "img/W1-02-4.jpg", "img/W1-02-5.jpg"], "lastNote": "", "lv": "A", "n": "تأكيد الوحدات اللي فيها قفل ذكي", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "خلف الكواليس", "status": "review", "t": "الدخول الذكي: من وصولك لين تفتح باب وحدتك", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-10-18-LI$i$,$j${"b": "صورة المدير داخل وحدة جاهزة، إضاءة طبيعية. تعيد صفحة الشركة نشره نفس اليوم.", "c": "في السوق شقق مفروشة كثيرة، وقليل منها يُدار كمنتج له معايير.\n\nفي ذا كابيتال سويتس بدأنا من سؤال بسيط: ما الذي يجعل الساكن يجدد، والمالك يطمئن؟\n\nلم تكن الإجابة في الأثاث وحده، بل في التشغيل:\n· تجهيز موحّد لكل وحدة\n· فحص قبل كل تسليم\n· صيانة بزمن استجابة معروف\n· أرقام نقيسها كل شهر\n\nخلال الأشهر القادمة سأشارك هنا ما نتعلمه من تشغيل وحداتنا في الرياض، بالأرقام الفعلية.\n\n#الرياض #العقار #السكن_المفروش #التشغيل_العقاري", "cta": "", "d": "2026-10-18", "designLink": "", "f": "منشور نصي من حساب المدير + صورة", "im": ["img/W1-03-LI.jpg"], "lastNote": "", "lv": "A", "n": "موافقة المدير على النص والصورة", "noteCount": 0, "p": "LI", "pubLink": "", "r": "", "s": "صوت المدير", "status": "review", "t": "لماذا نشغّل السكن المفروش بمعايير فندقية؟", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-10-20-IG$i$,$j${"b": "شريحة لكل خدمة بأيقونة وصورة حقيقية. الشريحة الأخيرة: رقم واتساب.", "c": "أكثر سؤال يوصلنا: الإيجار يشمل وش؟\n\nفي وحداتنا الإيجار الشهري يشمل: [الخدمات المؤكدة لكل وحدة].\nتدخل بشنطتك، والباقي علينا.\n\nللاستفسار عن الوحدات المتاحة: واتساب: 0503070157\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-10-20", "designLink": "", "f": "كاروسيل 5 شرائح", "im": ["img/W1-04-1.jpg", "img/W1-04-2.jpg", "img/W1-04-3.jpg", "img/W1-04-4.jpg", "img/W1-04-5.jpg"], "lastNote": "", "lv": "A", "n": "قائمة الخدمات المشمولة لكل وحدة من التشغيل (لا تُكتب «شامل كل شيء»)", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "التعريف", "status": "review", "t": "فاتورة واحدة: وش يشمل إيجارك الشهري عندنا؟", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-10-21-LI$i$,$j${"b": "قالب PDF بألوان البراند: صفحة لكل معيار برقم كبير وسطر شرح.", "c": "نشارك المعايير التي نلتزم بها في كل وحدة نشغّلها:\n\n1. [المعيار]\n2. [المعيار]\n3. [المعيار]\n4. [المعيار]\n5. [المعيار]\n6. [المعيار]\n7. [المعيار]\n\nالمعيار المكتوب هو ما يجعل الجودة لا تعتمد على اجتهاد شخص واحد، ولا تتغير من ساكن لآخر.\n\n#الرياض #العقار #السكن_المفروش #التشغيل_العقاري", "cta": "", "d": "2026-10-21", "designLink": "", "f": "كاروسيل PDF 8 صفحات", "im": ["img/W1-05-1.jpg", "img/W1-05-2.jpg", "img/W1-05-3.jpg", "img/W1-05-4.jpg"], "lastNote": "", "lv": "A", "n": "المعايير السبعة من التشغيل", "noteCount": 0, "p": "LI", "pubLink": "", "r": "", "s": "المعايير", "status": "review", "t": "معاييرنا التشغيلية في 7 نقاط", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-10-21-X$i$,$j${"b": "نفس محتوى LinkedIn بصياغة أقصر.", "c": "كيف نشغّل وحداتنا المفروشة في الرياض؟ 7 معايير نلتزم بها مع كل ساكن 🧵\n\n(تغريدة لكل معيار من منشور LinkedIn، والأخيرة: تابعنا لأرقام التشغيل الشهرية)", "cta": "", "d": "2026-10-21", "designLink": "", "f": "ثريد 8 تغريدات", "im": ["img/W1-06-X.jpg"], "lastNote": "", "lv": "A", "n": "", "noteCount": 0, "p": "X", "pubLink": "", "r": "2026-10-21-LI", "s": "المعايير", "status": "review", "t": "ثريد: معاييرنا التشغيلية في 7 نقاط", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-10-22-IG$i$,$j${"b": "بورتريه لكل شخص أثناء عمله، لا وقفة أمام الكاميرا.", "c": "ورا كل وحدة جاهزة فريق:\n[الاسم · الدور]\n[الاسم · الدور]\n[الاسم · الدور]\n\nهم اللي يجهّزون، يفحصون، ويردون عليك إذا احتجت شي.\nتعرّف عليهم في الصور.\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-10-22", "designLink": "", "f": "كاروسيل صور 4 شرائح", "im": [], "lastNote": "", "lv": "A", "n": "موافقة كل شخص على الظهور باسمه", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "الفريق", "status": "copy", "t": "الفريق اللي يشغّل وحدتك", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-10-25-IG$i$,$j${"b": "تايم لابس من زاوية ثابتة للوحدة من الخروج حتى الجاهزية، مع عدّاد ساعات على الشاشة.", "c": "ساكن يطلع… وش يصير بعدها؟\n\nتنظيف عميق، فحص كامل، تبديل المفارش، صيانة أي ملاحظة، وتصوير الوحدة من جديد.\nكل هذا خلال [X] ساعة قبل ما نستقبل الساكن الجاي.\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-10-25", "designLink": "", "f": "ريلز 30 ثانية (تايم لابس)", "im": [], "lastNote": "", "lv": "P", "n": "زمن الانتقال الفعلي بين ساكنين", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "خلف الكواليس", "status": "copy", "t": "48 ساعة بين ساكن وساكن", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-10-25-LI$i$,$j${"b": "صورة من التايم لابس.", "c": "أكثر ما يكلّف مالك العقار ليس الصيانة، بل الأيام التي تبقى فيها الوحدة شاغرة.\n\nلذلك نقيس زمن الانتقال بين ساكن وآخر. هدفنا [X] ساعة، ومتوسطنا الفعلي في [الشهر] كان [X].\n\nما يحدث في تلك الساعات:\n· تنظيف عميق\n· فحص كامل بقائمة مكتوبة\n· صيانة أي ملاحظة\n· تصوير الوحدة وتحديث الإعلان\n\nكل يوم نختصره هنا هو دخل للمالك وسكن جاهز لعميل ينتظر.\n\n#الرياض #العقار #السكن_المفروش #التشغيل_العقاري", "cta": "", "d": "2026-10-25", "designLink": "", "f": "منشور نصي + صورة", "im": [], "lastNote": "", "lv": "P", "n": "الهدف والمتوسط الفعلي لزمن الانتقال", "noteCount": 0, "p": "LI", "pubLink": "", "r": "2026-10-25-IG", "s": "إثبات الأداء", "status": "copy", "t": "أكثر ما يكلّف المالك: الأيام الشاغرة", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-10-27-IG$i$,$j${"b": "سؤال كبير في كل شريحة. الأخيرة: «احسبها صح» + رقم واتساب.", "c": "قبل ما توقّع إيجار سنوي، اسأل نفسك:\n1. كم مدة بقائك الفعلية في الرياض؟\n2. عندك أثاث أو بتشتري من الصفر؟\n3. الفواتير والإنترنت على مين؟\n4. لو تغيّرت ظروفك، وش شروط الخروج؟\n5. كم يوم بتضيع في التأسيس والتركيب؟\n\nالشهري المفروش مو دايم الأرخص، بس كثير مرات يكون الأوفر لك. احسبها صح.\n\nاحفظ المنشور لين تحتاجه.\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-10-27", "designLink": "", "f": "كاروسيل 7 شرائح", "im": [], "lastNote": "", "lv": "B", "n": "", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "معرفة السكن", "status": "copy", "t": "شهري مفروش أو سنوي؟ 5 أسئلة قبل ما تقرر", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-10-28-LI$i$,$j${"b": "بدون تصميم، نص فقط.", "c": "من واقع الاستفسارات التي وصلتنا خلال [الفترة]\n\nأكثر الشرائح طلباً: [الشرائح من بيانات الاستفسارات]\nأكثر ما يسألون عنه: [المدة، ما يشمله الإيجار، الموقع]\nمتوسط مدة الإقامة المطلوبة: [X] أشهر\n\nما يعنيه ذلك لمالك يفكر في التحويل للمفروش الشهري: الطلب الحقيقي يأتي من [الشريحة]، وهؤلاء يبحثون عن [الأولوية] أكثر من السعر.\n\n#الرياض #العقار #السكن_المفروش #التشغيل_العقاري", "cta": "", "d": "2026-10-28", "designLink": "", "f": "منشور نصي", "im": [], "lastNote": "", "lv": "P", "n": "ملخص بيانات الاستفسارات من نظام التتبّع", "noteCount": 0, "p": "LI", "pubLink": "", "r": "", "s": "من بيانات التشغيل", "status": "copy", "t": "من يطلب السكن المفروش الشهري في الرياض؟ من واقع استفساراتنا", "updatedAt": "2026-10-07T14:27:34.756Z", "updatedBy": "u_qrJLJWChmzjL048TJIDtxw"}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-10-28-X$i$,$j${"b": "", "c": "شهري مفروش أو إيجار سنوي؟ 5 أسئلة اسألها لنفسك قبل ما توقّع 🧵\n\n(تغريدة لكل سؤال من كاروسيل Instagram)", "cta": "", "d": "2026-10-28", "designLink": "", "f": "ثريد 6 تغريدات", "im": [], "lastNote": "", "lv": "B", "n": "", "noteCount": 0, "p": "X", "pubLink": "", "r": "2026-10-27-IG", "s": "معرفة السكن", "status": "copy", "t": "ثريد: شهري مفروش أو سنوي؟", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-10-29-IG$i$,$j${"b": "قالب «مشكلة وحلها»: ثلاث خانات (المشكلة · الحل · الوقت) وصورة من الموقع إن وجدت.", "c": "الأسبوع هذا: [المشكلة باختصار].\nوش سوّينا: [الإجراء].\nالوقت من البلاغ للحل: [X] ساعة.\n\nننشر هالقصص لأن التشغيل الحقيقي فيه مشاكل، والفرق في سرعة الحل.\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-10-29", "designLink": "", "f": "منشور ثابت بالقالب + ستوري", "im": [], "lastNote": "", "lv": "P", "n": "قصة حقيقية من التشغيل هذا الأسبوع + موافقة المدير", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "مشكلة وحلها", "status": "copy", "t": "مشكلة صارت وكيف حليناها #1", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-01-IG$i$,$j${"b": "لقطات قريبة سريعة لكل بند مع علامة صح على الشاشة.", "c": "قبل ما نسلّمك المفتاح، نمر على [X] نقطة:\nالماء الحار، التكييف، الإضاءة، القفل الذكي، الإنترنت، نظافة الأسطح… والقائمة تكمل.\n\nما نسلّم وحدة ما عدّت القائمة كاملة.\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-11-01", "designLink": "", "f": "ريلز 20 ثانية", "im": [], "lastNote": "", "lv": "A", "n": "عدد بنود قائمة الفحص", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "المعايير", "status": "copy", "t": "قائمة الفحص: وش نشيّك قبل ما نسلّمك المفتاح", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-01-LI$i$,$j${"b": "", "c": "في التشغيل اليومي لا توجد وحدة بلا ملاحظات. الفرق في سرعة الاستجابة ووضوح الإجراء.\n\nهذا الأسبوع: [المشكلة].\nالإجراء: [الخطوات].\nالزمن من البلاغ إلى الحل: [X] ساعة.\nما غيّرناه حتى لا تتكرر: [التعديل].\n\nننشر هذه الحالات لأن المالك يستحق أن يعرف كيف يُدار عقاره عند المشاكل، لا عند الصور الجميلة فقط.\n\n#الرياض #العقار #السكن_المفروش #التشغيل_العقاري", "cta": "", "d": "2026-11-01", "designLink": "", "f": "منشور نصي", "im": [], "lastNote": "", "lv": "P", "n": "نفس قصة 29 أكتوبر بصياغة مهنية", "noteCount": 0, "p": "LI", "pubLink": "", "r": "2026-10-29-IG", "s": "مشكلة وحلها", "status": "copy", "t": "مشكلة تشغيلية وكيف حُلّت", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-03-IG$i$,$j${"b": "سؤال وجواب في كل شريحة بقالب واحد.", "c": "جمعنا أكثر 6 أسئلة توصلنا وجاوبناها:\n· أقل مدة للعقد؟ [الإجابة]\n· فيه تأمين؟ [الإجابة]\n· وش يشمل الإيجار؟ [الإجابة]\n· فيه مواقف؟ [الإجابة]\n· الصيانة على مين؟ [الإجابة]\n· أقدر أعاين قبل ما أحجز؟ [الإجابة]\n\nاحفظ المنشور لو تدوّر سكن شهري.\nواتساب: 0503070157\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-11-03", "designLink": "", "f": "كاروسيل 7 شرائح", "im": [], "lastNote": "", "lv": "B", "n": "إجابات معتمدة حسب سياسة العقود", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "أسئلة السكان", "status": "copy", "t": "أكثر 6 أسئلة توصلنا على الواتساب", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-04-LI$i$,$j${"b": "صفحة لكل سؤال، والصفحة الأخيرة: «تابع تقريرنا الشهري».", "c": "قبل أن تسلّم عقارك لأي جهة تشغيل، اسألها:\n\n1. كيف تقيسون نسبة الإشغال، وكم كانت آخر 3 أشهر؟\n2. كم يستغرق تجهيز الوحدة قبل أول ساكن؟\n3. كم يوماً تبقى الوحدة شاغرة بين ساكنين في المتوسط؟\n4. من يتحمل الصيانة، وما زمن الاستجابة للبلاغ؟\n5. كيف يُحدد السعر، ومن يعتمده؟\n6. كيف ومتى تصلني التقارير؟\n7. ما شروط إنهاء الاتفاق؟\n8. هل تنشرون أرقام تشغيلكم؟\n\nنحن نجيب عن هذه الأسئلة علناً كل شهر.\n\n#الرياض #العقار #السكن_المفروش #التشغيل_العقاري", "cta": "", "d": "2026-11-04", "designLink": "", "f": "كاروسيل PDF 9 صفحات", "im": [], "lastNote": "", "lv": "B", "n": "", "noteCount": 0, "p": "LI", "pubLink": "", "r": "", "s": "معرفة السوق", "status": "copy", "t": "8 أسئلة اسألها لأي مشغّل قبل أن تسلّمه عقارك", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-04-X$i$,$j${"b": "", "c": "عندك عقار وتفكر تسلّمه لشركة تشغيل؟ اسألها هذي الأسئلة الثمانية قبل ما توقّع 🧵", "cta": "", "d": "2026-11-04", "designLink": "", "f": "ثريد 9 تغريدات", "im": [], "lastNote": "", "lv": "B", "n": "", "noteCount": 0, "p": "X", "pubLink": "", "r": "2026-11-04-LI", "s": "معرفة السوق", "status": "copy", "t": "ثريد: 8 أسئلة قبل ما تسلّم عقارك لمشغّل", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-05-IG$i$,$j${"b": "قالب التقرير: رقم كبير بالذهبي في كل شريحة، وسطر شرح، والفترة وعدد الوحدات أسفلها.", "c": "أول تقرير شهري لنا. بننشر أرقام تشغيلنا كل شهر بنفس القالب:\n\nالإشغال: [X]% على [Y] وحدة\nوحدات تسكّنت هذا الشهر: [X]\nمتوسط مدة التسكين: [X] يوم\nمتوسط زمن تجهيز الوحدة: [X] يوم\n\nليش ننشرها؟ لأن الأرقام أصدق من أي كلام عن أنفسنا.\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-11-05", "designLink": "", "f": "كاروسيل 6 شرائح بقالب التقرير", "im": [], "lastNote": "", "lv": "P", "n": "ملف أرقام أكتوبر من التشغيل بحلول 3 نوفمبر + موافقة المدير", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "تقرير الشهر", "status": "copy", "t": "تقرير أكتوبر · The Capital Monthly #1", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-08-IG$i$,$j${"b": "لقطات من يوم حقيقي: جولة فحص، مكالمة مع فريق الصيانة، تسليم مفتاح، مراجعة جدول اليوم.", "c": "[الاسم]، مدير التشغيل.\nيومه يبدأ [الساعة] وما يخلص إلا لما تكون كل وحدة جاهزة وكل بلاغ له رد.\nتابع معانا يوم كامل من التشغيل.\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-11-08", "designLink": "", "f": "ريلز 40 ثانية", "im": [], "lastNote": "", "lv": "A", "n": "موافقة مدير التشغيل", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "الفريق", "status": "copy", "t": "يوم مع مدير التشغيل", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-08-LI$i$,$j${"b": "نفس قالب Instagram بمقاس PDF.", "c": "ننشر من هذا الشهر تقريراً شهرياً بأرقام تشغيلنا، بنفس المؤشرات كل مرة:\n\nالإشغال: [X]% على [Y] وحدة\nالوحدات التي تسكّنت: [X]\nمتوسط مدة التسكين: [X] يوماً\nمتوسط زمن التجهيز: [X] يوماً\n\nملاحظتي على الشهر: [قراءة المدير في سطرين].\n\nالتقرير الكامل في الملف المرفق.\n\n#الرياض #العقار #السكن_المفروش #التشغيل_العقاري", "cta": "", "d": "2026-11-08", "designLink": "", "f": "كاروسيل PDF + منشور نصي", "im": [], "lastNote": "", "lv": "P", "n": "نفس أرقام 5 نوفمبر + قراءة المدير", "noteCount": 0, "p": "LI", "pubLink": "", "r": "2026-11-05-IG", "s": "تقرير الشهر", "status": "copy", "t": "تقرير أكتوبر + تعليق المدير", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-10-IG$i$,$j${"b": "نفس قالب #1.", "c": "الأسبوع هذا: [المشكلة باختصار].\nوش سوّينا: [الإجراء].\nالوقت من البلاغ للحل: [X] ساعة.\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-11-10", "designLink": "", "f": "منشور ثابت بالقالب + ستوري", "im": [], "lastNote": "", "lv": "P", "n": "قصة حقيقية جديدة من التشغيل", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "مشكلة وحلها", "status": "copy", "t": "مشكلة صارت وكيف حليناها #2", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-11-LI$i$,$j${"b": "", "c": "ليس كل عقار يناسبه التحويل إلى سكن مفروش شهري.\n\nيناسبك غالباً إذا:\n· الحي عليه طلب من موظفين ومنتقلين\n· الوحدات صغيرة أو متوسطة\n· تعاني من شغور طويل أو تحصيل متعثر\n\nقد لا يناسبك إذا:\n· المبنى يحتاج ترميماً كبيراً قبل التشغيل\n· الطلب في الحي سنوي عائلي بالأساس\n· لا تريد تحمّل تكلفة التجهيز الأولى\n\nإذا عندك وحدات وتريد قراءة أولية لعقارك، تواصل معنا لاستشارة.\n\n#الرياض #العقار #السكن_المفروش #التشغيل_العقاري", "cta": "إذا عندك وحدات وتريد قراءة أولية لعقارك، راسلنا", "d": "2026-11-11", "designLink": "", "f": "منشور نصي", "im": [], "lastNote": "", "lv": "C", "n": "", "noteCount": 0, "p": "LI", "pubLink": "", "r": "", "s": "حسابات المالك", "status": "copy", "t": "متى يناسب عقارك التحويل للمفروش الشهري، ومتى لا يناسب؟", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-11-X$i$,$j${"b": "صورة الشريحة الأولى من التقرير.", "c": "أرقام تشغيلنا في أكتوبر:\nالإشغال [X]% على [Y] وحدة\nتسكّنت [X] وحدات\nمتوسط مدة التسكين [X] يوم\n\nننشرها كل شهر.", "cta": "", "d": "2026-11-11", "designLink": "", "f": "تغريدة + صورة", "im": [], "lastNote": "", "lv": "P", "n": "", "noteCount": 0, "p": "X", "pubLink": "", "r": "2026-11-05-IG", "s": "تقرير الشهر", "status": "copy", "t": "أرقام أكتوبر في منشور واحد", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-12-IG$i$,$j${"b": "سبب في كل شريحة بصورة من وحدة حقيقية.", "c": "يوصلنا كل أسبوع موظفين منتقلين للرياض لوظيفة أو مشروع.\nأكثر الأسباب اللي يذكرونها لاختيار الشهري المفروش:\n[الأسباب من بيانات الاستفسارات]\n\nلو أنت منهم، وش أهم شي تدوّره في السكن؟ قولنا بالتعليقات.\n\n#الرياض #سكن_شهري #شقق_مفروشة", "cta": "", "d": "2026-11-12", "designLink": "", "f": "كاروسيل 5 شرائح", "im": [], "lastNote": "", "lv": "P", "n": "الأسباب الأكثر تكراراً من الاستفسارات", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "من بيانات التشغيل", "status": "copy", "t": "الموظف المنتقل للرياض: وش يدوّر في السكن؟ من واقع استفساراتنا", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$2026-11-15-IG$i$,$j${"b": "الوحدة فارغة يوم 1 ← التركيب مسرّعاً ← الفحص ← نفس الزاوية جاهزة يوم [X]. سطر الختام: «تسكّنت بعد [X] أيام من جاهزيتها» إن توفر.", "c": "", "cta": "", "d": "2026-11-15", "designLink": "", "f": "ريلز 40 ثانية", "im": [], "lastNote": "", "lv": "P", "n": "زمن التجهيز الفعلي + رقم ترخيص الرمال", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "من الصفر للمفتاح", "status": "idea", "t": "من الصفر للمفتاح #1: استديو الرمال", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
