insert into public.posts(id,data) values ($i$setup-avatar$i$,$j${"b": "الشعار الذهبي على خلفية الفحمي #1F2427، بمساحة كافية حول الشعار عشان ما يتقصش في الدائرة. نسخة واحدة لـ Instagram وX وLinkedIn وواتساب.", "c": "", "cta": "", "d": "2026-10-11", "designLink": "", "f": "1080×1080 · تُقصّ دائرية · واضحة في 110px", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "ملف الشعار الأصلي بجودة عالية (SVG أو PNG شفاف)", "noteCount": 0, "p": "ALL", "pubLink": "", "r": "", "s": "الحسابات", "status": "design", "t": "صورة البروفايل لكل الحسابات", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$setup-hl-about$i$,$j${"b": "قالب ستوري بألوان البراند مع صور من جلسة التصوير.", "c": "ستوري 1: مين إحنا؟ ذا كابيتال سويتس، نشغّل وحدات مفروشة بالشهر في الرياض.\nستوري 2: وش يميزنا؟ تشغيل بمعايير فندقية: تنظيف، صيانة، دخول ذكي.\nستوري 3: وين نشغّل؟ [الأحياء المشغّلة حالياً].\nستوري 4: للاستفسار: واتساب 0503070157", "cta": "", "d": "2026-10-14", "designLink": "", "f": "4 ستوريز", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "تأكيد الأحياء المشغّلة", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "الهايلايتس", "status": "copy", "t": "هايلايت «من نحن»", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
