insert into public.posts(id,data) values ($i$setup-hl-covers$i$,$j${"b": "خمس أغلفة بنفس الأسلوب: خلفية فحمي #1F2427، أيقونة خطية ذهبية #E2C466 في الوسط، بدون نص داخل الدائرة. الأيقونات: مبنى، علامة صح، دبوس خريطة، علامة استفهام، رسم بياني.", "c": "من نحن · المعايير · الأحياء · أسئلة · التقارير", "cta": "", "d": "2026-10-13", "designLink": "", "f": "1080×1920 · الأيقونة في دائرة الوسط · خط عربي واضح", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "الهايلايتس", "status": "design", "t": "أغلفة الهايلايتس (5)", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$setup-hl-faq$i$,$j${"b": "قالب سؤال وجواب ثابت.", "c": "وش يشمل الإيجار الشهري؟ [الخدمات المؤكدة لكل وحدة]\nأقل مدة للإيجار؟ شهر.\nكيف الدخول؟ دخول ذكي من جوالك.\nمين يتابع الصيانة؟ فريقنا، وزمن الاستجابة [المدة].\nفيه تأمين؟ [التأكيد من التشغيل]\nكيف أحجز؟ واتساب 0503070157", "cta": "", "d": "2026-10-14", "designLink": "", "f": "6 ستوريز سؤال وجواب", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "إجابات التشغيل على الأسئلة المظللة", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "الهايلايتس", "status": "copy", "t": "هايلايت «أسئلة»", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$setup-hl-reports$i$,$j${"b": "ستوري افتتاحي بسيط بنفس قالب التقرير الشهري.", "c": "ستوري افتتاحي: «هنا ننشر أرقام تشغيلنا كل شهر بنفس المؤشرات.»\nبعدها يُضاف تقرير كل شهر.", "cta": "", "d": "2026-10-14", "designLink": "", "f": "يبدأ فاضي ويتملى من 5 نوفمبر", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "الهايلايتس", "status": "idea", "t": "هايلايت «التقارير»", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$setup-hl-standards$i$,$j${"b": "لقطات من جلسة التصوير لبنود الفحص.", "c": "ستوري 1: قبل ما نسلّمك المفتاح، كل وحدة تمر على قائمة فحص.\nستوري 2–4: [بنود قائمة الفحص] بند في كل ستوري مع صورة.\nستوري 5: هذا معيارنا مع كل ساكن.", "cta": "", "d": "2026-10-14", "designLink": "", "f": "5 ستوريز", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "بنود قائمة الفحص من التشغيل", "noteCount": 0, "p": "IG", "pubLink": "", "r": "", "s": "الهايلايتس", "status": "idea", "t": "هايلايت «المعايير»", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
