insert into public.posts(id,data) values ($i$setup-li-banner$i$,$j${"b": "صورة وحدة جاهزة بإضاءة دافئة مع طبقة فحمي خفيفة، والنص يمين. خلي المنطقة اليسار فاضية لأن صورة البروفايل تغطيها في الحساب الشخصي.", "c": "النص على الغلاف (اختياري): تشغيل السكن المفروش بمعايير فندقية · الرياض", "cta": "", "d": "2026-10-12", "designLink": "", "f": "1128×191 للصفحة · 1584×396 للحساب الشخصي", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "صورة من جلسة التصوير", "noteCount": 0, "p": "LI", "pubLink": "", "r": "", "s": "الحسابات", "status": "design", "t": "غلاف صفحة LinkedIn وغلاف حساب المدير", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$setup-li-manager$i$,$j${"b": "صورة شخصية احترافية داخل وحدة جاهزة.", "c": "العنوان المهني:\n[الاسم] · [المسمى] في ذا كابيتال سويتس | تشغيل الوحدات المفروشة في الرياض\n\nالخبرة: [المسمى] · ذا كابيتال سويتس (مربوطة بصفحة الشركة)", "cta": "", "d": "2026-10-12", "designLink": "", "f": "الصورة · العنوان المهني · الخبرة مربوطة بالصفحة", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "موافقة المدير على الظهور، وصورته", "noteCount": 0, "p": "LI", "pubLink": "", "r": "", "s": "الحسابات", "status": "idea", "t": "تحديث حساب المدير على LinkedIn", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$setup-li-page$i$,$j${"b": "", "c": "السطر التعريفي:\nتشغيل الوحدات السكنية المفروشة في الرياض بمعايير فندقية\n\nالنبذة:\nذا كابيتال سويتس شركة سعودية تشغّل وحدات سكنية مفروشة للإيجار الشهري في الرياض. نعمل بمعايير تشغيل مكتوبة تشمل التجهيز الموحّد، والفحص قبل كل تسليم، والصيانة بزمن استجابة محدد، ونقيس أداء وحداتنا شهرياً وننشر أرقامه.\n\nالموقع: https://thecapitalsuites.sa\nالقطاع: العقارات\nرخصة فال: 1200046434", "cta": "", "d": "2026-10-11", "designLink": "", "f": "الاسم · الشعار · السطر التعريفي · النبذة · الموقع · القطاع", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "موافقة الإدارة على النبذة", "noteCount": 0, "p": "LI", "pubLink": "", "r": "", "s": "الحسابات", "status": "copy", "t": "صفحة الشركة على LinkedIn", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$setup-ops-data$i$,$j${"b": "", "c": "قائمة الفحص قبل التسكين\nما يشمله الإيجار لكل وحدة\nزمن التجهيز الفعلي بين ساكنين\nزمن الاستجابة للصيانة\nالأحياء المشغّلة حالياً", "cta": "", "d": "2026-10-11", "designLink": "", "f": "قائمة تجمعها من فريق التشغيل", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "كل الأجزاء بين [ ] في المنشورات والتأسيس تعتمد على البيانات دي", "noteCount": 0, "p": "ALL", "pubLink": "", "r": "", "s": "الإنتاج", "status": "idea", "t": "بيانات من التشغيل", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$setup-shoot$i$,$j${"b": "", "c": "المطلوب: واجهة المبنى، القفل الذكي، الدخول الذكي خطوة بخطوة، بورتريه الفريق، لقطات بنود قائمة الفحص، صور الأحياء.", "cta": "", "d": "2026-10-11", "designLink": "", "f": "نصف يوم · الأحد 11 أكتوبر", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "تأكيد الوحدة الجاهزة للتصوير وحضور الفريق", "noteCount": 0, "p": "ALL", "pubLink": "", "r": "", "s": "الإنتاج", "status": "idea", "t": "جلسة تصوير ما قبل الإطلاق", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$setup-templates$i$,$j${"b": "قوالب ثابتة لكل سلسلة: التعريف، تقرير الشهر، مشكلة وحلها، حي في دقيقة، حسبة المالك. الألوان: فحمي #1F2427، ذهبي #E2C466 / #C29B3C، عاجي #F7F4EC. الخطوط: Alexandria للعناوين وIBM Plex Sans Arabic للنص.", "c": "", "cta": "", "d": "2026-10-13", "designLink": "", "f": "قالب لكل سلسلة: 4:5 للمنشور و9:16 للستوري", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "", "noteCount": 0, "p": "ALL", "pubLink": "", "r": "", "s": "الإنتاج", "status": "design", "t": "قوالب السلاسل الثابتة", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$setup-wa$i$,$j${"b": "", "c": "الوصف: وحدات فندقية مفروشة بالشهر في الرياض\nساعات العمل: [الساعات المعتمدة]\n\nرسالة الترحيب:\nأهلاً بك في ذا كابيتال سويتس. وش الحي اللي يناسبك، ومتى تبي تسكن؟ وبنرسل لك الوحدات المتاحة.\n\nرسالة خارج الدوام:\nوصلتنا رسالتك، وبنرد عليك أول ما يبدأ الدوام [الساعة].", "cta": "", "d": "2026-10-12", "designLink": "", "f": "الاسم · الوصف · ساعات العمل · رسالة الترحيب", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "تأكيد أن الرقم على واتساب بزنس، وساعات العمل", "noteCount": 0, "p": "WA", "pubLink": "", "r": "", "s": "الحسابات", "status": "copy", "t": "ملف واتساب بزنس", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
insert into public.posts(id,data) values ($i$setup-x-profile$i$,$j${"b": "الهيدر: نفس تصميم غلاف LinkedIn بمقاس 1500×500.", "c": "وحدات فندقية مفروشة بالشهر في الرياض · تشغيل بمعايير فندقية · ننشر أرقام تشغيلنا كل شهر · فال 1200046434\nالرابط: https://thecapitalsuites.sa", "cta": "", "d": "2026-10-12", "designLink": "", "f": "البايو 160 حرف · الهيدر 1500×500", "im": [], "kind": "setup", "lastNote": "", "lv": "A", "n": "", "noteCount": 0, "p": "X", "pubLink": "", "r": "", "s": "الحسابات", "status": "copy", "t": "بايو X والهيدر", "tm": "", "updatedAt": "", "updatedBy": ""}$j$::jsonb) on conflict (id) do update set data=excluded.data;
